import fs from "fs";
import path from "path";

const workspaceRoot = process.cwd();
const hudPath = path.join(workspaceRoot, "HUD.md");

// Debounce timer to prevent terminal flickering on rapid OS file events
let timeout: NodeJS.Timeout | null = null;

const renderHUD = () => {
  if (!fs.existsSync(hudPath)) {
    process.stdout.write("\x1Bc"); // Clear terminal
    console.log(
      "\x1b[33m%s\x1b[0m",
      "⚠️ Waiting for HUD.md to be generated by /context-sync...",
    );
    return;
  }

  try {
    const content = fs.readFileSync(hudPath, "utf8");

    // Clear the terminal screen (cross-platform)
    process.stdout.write("\x1Bc");

    // Print the Cyan Header
    console.log("\x1b[36m%s\x1b[0m", "=== 🛸 TOPHAT COMMAND CENTER ===\n");

    // Print the raw Markdown content
    console.log(content);

    // Print the Grey Footer
    console.log(
      "\x1b[90m%s\x1b[0m",
      "\n[Watching for swarm state changes... (Press Ctrl+C to exit)]",
    );
  } catch (err) {
    // Fail silently if the file is locked mid-write by an agent
  }
};

// Initial render
renderHUD();

// Watch the root directory for changes to HUD.md
fs.watch(workspaceRoot, (eventType, filename) => {
  if (filename === "HUD.md") {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(renderHUD, 50); // 50ms debounce
  }
});
